        if (c >= 0x20 && c < 0x80 && c != '"' && c != '\\') { i++; continue; }
        if (i > run) vu_str_cat_bytes(o, s + run, i - run);
        if (c == '"' || c == '\\') { char e[2] = {'\\', (char)c}; vu_jcat(o, e, 2); i++; }
