static void vu_jenc_Byte(vu_str *o, const uint8_t *v) { int64_t x = *v; vu_jenc_Int(o, &x); }
static void vu_jenc_Bool(vu_str *o, const bool *v) { if (*v) vu_jcat(o, "true", 4); else vu_jcat(o, "false", 5); }
