    if (n < 0) vu_fail(line, "reserve(%lld): the count can't be negative", (long long)n);
    if (n <= l->cap - l->len) return;
    if (n > (int64_t)(PTRDIFF_MAX / sizeof(T_Snap)) - l->len) vu_oom();
    int64_t c = l->len + n;
    T_Snap *d = (T_Snap *)realloc(l->data, (size_t)c * sizeof(T_Snap));
    if (!d) vu_oom();
    l->data = d;
    l->cap = c;
