    if (!m->nidx) {
        if (m->nents >= VU_SMALL_MAP) vu_mbig_M3_StrL_S_IndexEntry(m);
    } else if ((m->nents + 1) * 4 > m->nidx * 3) vu_mindex_M3_StrL_S_IndexEntry(m, (m->live + 1) * 2);
