        int64_t c = m->cap == 0 ? 4 : m->cap == 4 ? 12 : m->cap + m->cap / 2;
        ME_M3_StrL_S_IndexEntry *d = (ME_M3_StrL_S_IndexEntry *)realloc(m->ents, (size_t)c * sizeof(ME_M3_StrL_S_IndexEntry));
        if (!d) vu_oom();
